// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // A minimal benign callee that always returns true for transferFrom signature
    contract Helper {
        // match selector: transferFrom(address,address,uint256)
        function transferFrom(address, address, uint) external pure returns (bool) {
            return true;
        }
    }

    function setUp() public { c = new C(); }

    // fuzzed params: from, v (amount), and an array length indicator; we cannot fuzz raw address[] directly
    // so we fuzz one address and a length (will build an array of that address repeated length times)
    function testFuzz_property(address from, address callee, uint256 v, uint256 len) public {
        // keep len in a reasonable bound but wide enough to include zero check
        len = bound(len, 0, 5);

        // we need a callee with code because low-level call to EOA would succeed but not execute transferFrom
        // deploy a Helper and use its address as callee; still fuzz 'callee' to ensure fuzzer varies other inputs
        Helper h = new Helper();
        address caddress = address(h);

        // build tos array of length 'len' filled with 'from' (could be any addresses)
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) {
            tos[i] = from;
        }

        // require in contract enforces tos.length > 0; two cases:
        // - len == 0: both reference and mutant will revert. We test only behaviour when call completes.
        // - len > 0: call should complete (Helper.transferFrom returns true), reference returns true,
        //   mutant returns false. We'll observe the returned boolean via try/catch on call.

        bool ok;
        try c.transfer(from, caddress, tos, v) returns (bool ret) {
            // call completed
            ok = ret;
        } catch {
            // reverted
            ok = false;
        }

        // General rule: when the call completes, reference returns true (so ok == true for len>0)
        // For len==0 the call reverts and ok==false; we accept that. So assert that if tos length>0 then ok is true.
        if (len > 0) {
            assertTrue(ok);
        } else {
            // when len==0 the call must revert, so ok must be false
            assertTrue(!ok);
        }
    }
}
